// Runs when any LendLoop workflow fails after its retries. Reports the failure to
// Convex so it shows in the app's admin view, and logs it here as well.
const crypto = require("crypto");
const e = $input.first().json;
const report = {
  executionId: String((e.execution && e.execution.id) || `trigger-${Date.now()}`),
  workflowName: (e.workflow && e.workflow.name) || "unknown workflow",
  node: (e.execution && e.execution.lastNodeExecuted) || undefined,
  message: String(
    (e.execution && e.execution.error && e.execution.error.message) ||
      (e.trigger && e.trigger.error && e.trigger.error.message) ||
      "Unknown error",
  ).slice(0, 1000),
};
console.error("[LendLoop] workflow failed", JSON.stringify(report));

const path = "/n8n/workflow-error";
const body = JSON.stringify(report);
const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = crypto
  .createHmac("sha256", $env.N8N_TO_CONVEX_SECRET)
  .update(`${timestamp}.POST.${path}.${body}`)
  .digest("hex");
return [{ json: { url: `${$env.CONVEX_SITE_URL}${path}`, body, timestamp, signature: `sha256=${signature}` } }];
